// Nó: "Validar clientes" (Code · Run Once for All Items)
// Valida e padroniza os clientes enviados pelo RPA antes de qualquer cruzamento.
//
// Entrada : 1 item do Webhook  -> { body: { clientes: [{ nome, email, saldo, perfil }] } }
// Saída   : 1 item             -> { recebidos, validos: [...], ignorados: [{ indice, nome, motivos }] }

const PERFIS_VALIDOS = { conservador: 'Conservador', moderado: 'Moderado', arrojado: 'Arrojado' };
const EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

const semAcento = (texto) =>
  String(texto ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').trim().toLowerCase();

// "R$ 12.500,00" -> 12500 | "850" -> 850 | 1200.5 -> 1200.5 | inválido -> NaN
function paraNumero(valor) {
  if (typeof valor === 'number') return valor;
  const limpo = String(valor ?? '').replace(/[^\d,.-]/g, '');
  if (!limpo) return NaN;
  if (limpo.includes(',')) return Number(limpo.replace(/\./g, '').replace(',', '.'));
  if (/^-?\d{1,3}(\.\d{3})+$/.test(limpo)) return Number(limpo.replace(/\./g, ''));
  return Number(limpo);
}

const body = $input.first().json.body ?? {};
const lista = Array.isArray(body.clientes) ? body.clientes : [];

const validos = [];
const ignorados = [];
const emailsVistos = new Set();

lista.forEach((cliente, indice) => {
  const c = cliente && typeof cliente === 'object' ? cliente : {};
  const motivos = [];

  const nome = String(c.nome ?? '').trim();
  const email = String(c.email ?? '').trim().toLowerCase();
  const perfil = PERFIS_VALIDOS[semAcento(c.perfil)];
  const saldo = paraNumero(c.saldo);

  if (!nome) motivos.push('nome ausente');
  if (!EMAIL_REGEX.test(email)) motivos.push('e-mail inválido');
  else if (emailsVistos.has(email)) motivos.push('e-mail duplicado no lote');
  if (!perfil) motivos.push('perfil desconhecido (use Conservador, Moderado ou Arrojado)');
  if (!Number.isFinite(saldo) || saldo < 0) motivos.push('saldo inválido');

  if (motivos.length) {
    ignorados.push({ indice, nome: nome || null, motivos });
    return;
  }
  emailsVistos.add(email);
  validos.push({ nome, email, perfil, saldo });
});

return [{ json: { recebidos: lista.length, validos, ignorados } }];

// Nó: "Cruzar clientes x investimentos" (Code · Run Once for All Items)
// Cruza cada cliente validado com as opções do data.csv e gera a mensagem (template por perfil).
//
// Entrada : 1 item do nó "Agrupar produtos" -> { produtos: [{ perfil, produto, minimo, rentabilidade }] }
//           + clientes validados, lidos do nó "Validar clientes"
// Saída   : 1 item por cliente -> { nome, email, perfil, saldo, produtosRecomendados, assunto, mensagem, geradoPor }

const semAcento = (texto) =>
  String(texto ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').trim().toLowerCase();

// 12500 -> "R$ 12.500,00" (formatação manual: não depende do ICU do servidor)
const brl = (n) => 'R$ ' + n.toFixed(2).replace('.', ',').replace(/\B(?=(\d{3})+(?!\d))/g, '.');

// "6.2%" -> "6,2%" | "IPCA+6.0%" -> "IPCA+6,0%" | "Variável" -> "Variável"
const rentabilidadePtBr = (texto) => String(texto).trim().replace('.', ',');

// Texto de cada perfil (MVP: mensagens estáticas, conforme o roteiro do desafio)
const PERFIS = {
  conservador: {
    abertura: 'Seu perfil prioriza segurança e liquidez, por isso selecionamos opções de renda fixa com menor risco.',
    fechamento: 'Concentrar sua carteira em renda fixa ajuda a proteger o patrimônio e a manter sua reserva disponível quando precisar.',
    risco: 'Rentabilidade e liquidez variam conforme o produto e o emissor.',
  },
  moderado: {
    abertura: 'Seu perfil busca equilíbrio entre segurança e crescimento, por isso combinamos renda fixa com exposição moderada à renda variável.',
    fechamento: 'Dividir o capital entre renda fixa e multimercado permite buscar retorno maior sem abrir mão de estabilidade.',
    risco: 'Fundos e títulos indexados podem oscilar no curto prazo.',
  },
  arrojado: {
    abertura: 'Seu perfil aceita oscilações em troca de maior potencial de retorno, por isso destacamos opções de renda variável.',
    fechamento: 'Diversificar entre ETFs e fundos de ações reduz a concentração de risco; mantenha também uma reserva de liquidez.',
    risco: 'Renda variável e criptomoedas podem gerar perdas, inclusive do capital investido.',
  },
};

const AVISO = 'Esta mensagem é informativa e não constitui recomendação de investimento; rentabilidade passada não garante resultado futuro.';

// ---------- 1. Entradas ----------
const { validos } = $('Validar clientes').first().json;

const produtos = ($input.first().json.produtos ?? [])
  .map((p) => ({
    perfil: semAcento(p.perfil),
    produto: String(p.produto ?? '').trim(),
    minimo: Number(String(p.minimo ?? '').replace(',', '.')),
    rentabilidade: String(p.rentabilidade ?? '').trim(),
  }))
  .filter((p) => p.perfil && p.produto && Number.isFinite(p.minimo));

// ---------- 2. Cruzamento + mensagem ----------
const itens = validos.map((cliente) => {
  const chave = semAcento(cliente.perfil);
  const texto = PERFIS[chave];
  const primeiroNome = cliente.nome.split(/\s+/)[0];

  const doPerfil = produtos.filter((p) => p.perfil === chave);
  const elegiveis = doPerfil
    .filter((p) => p.minimo <= cliente.saldo)
    .map((p) => ({
      produto: p.produto,
      minimo: p.minimo,
      minimoFormatado: brl(p.minimo),
      rentabilidade: p.rentabilidade,
      rentabilidadeFormatada: rentabilidadePtBr(p.rentabilidade),
    }));

  let blocoProdutos;
  if (elegiveis.length) {
    blocoProdutos =
      'Opções compatíveis com o seu perfil e o seu saldo:\n' +
      elegiveis
        .map((p) => `• ${p.produto} — aporte mínimo ${p.minimoFormatado} — rentabilidade ${p.rentabilidadeFormatada}`)
        .join('\n');
  } else if (doPerfil.length) {
    const menor = doPerfil.reduce((a, b) => (b.minimo < a.minimo ? b : a));
    blocoProdutos =
      `Hoje o seu saldo ainda não alcança o aporte mínimo das opções do seu perfil. ` +
      `A porta de entrada é ${menor.produto}, com aporte mínimo de ${brl(menor.minimo)} ` +
      `(faltam ${brl(menor.minimo - cliente.saldo)}).`;
  } else {
    blocoProdutos = 'No momento não há opções cadastradas para o seu perfil.';
  }

  const mensagem = [
    `Olá, ${primeiroNome}!`,
    '',
    `Seu perfil de investidor é ${cliente.perfil} e o seu saldo atual é ${brl(cliente.saldo)}.`,
    texto.abertura,
    '',
    blocoProdutos,
    '',
    elegiveis.length ? texto.fechamento : 'Quando o saldo permitir, teremos prazer em apresentar as melhores alternativas.',
    '',
    `${AVISO} ${texto.risco}`,
  ].join('\n');

  return {
    json: {
      nome: cliente.nome,
      email: cliente.email,
      perfil: cliente.perfil,
      saldo: cliente.saldo,
      saldoFormatado: brl(cliente.saldo),
      produtosRecomendados: elegiveis,
      assunto: `${primeiroNome}, veja opções de investimento para o seu perfil ${cliente.perfil}`,
      mensagem,
      geradoPor: 'template',
    },
  };
});

return itens;

// Nó: "Montar resposta" (Code · Run Once for All Items)
// Consolida as mensagens em um único JSON — é o que o Webhook devolve ao script de RPA.
//
// Entrada : 1 item por cliente (saída de "Cruzar clientes x investimentos")
// Saída   : 1 item -> { resumo: { recebidos, processados, ignorados }, mensagens: [...], ignorados: [...] }

const mensagens = $input.all().map((item) => item.json);
const { recebidos, ignorados } = $('Validar clientes').first().json;

return [
  {
    json: {
      resumo: { recebidos, processados: mensagens.length, ignorados: ignorados.length },
      mensagens,
      ignorados,
    },
  },
];
